#define LORA_RX 16
#define LORA_TX 17
#define M0 18
#define M1 19

HardwareSerial LoRa(2);

void setup() {
  Serial.begin(115200);

  pinMode(M0, OUTPUT);
  pinMode(M1, OUTPUT);

  // Normal reception mode
  digitalWrite(M0, LOW);
  digitalWrite(M1, LOW);

  delay(500);

  LoRa.begin(9600, SERIAL_8N1, LORA_RX, LORA_TX);

  Serial.println("LORA RECEIVER READY");
}

void loop() {
  if (LoRa.available()) {
    String message = LoRa.readStringUntil('\n');
    Serial.print("Received: ");
    Serial.println(message);
  }
}
